// ===== Ravenstack churn scoring — embedded in n8n =====
// Replaces the external Python scoring API so nothing depends on localhost.
// Reads the CSVs fetched by the upstream HTTP nodes, scores every active
// account with the Phase 1 rule-based model, and returns the top 20.

// --- Reference date ---
// The Ravenstack dataset runs Jan 2023 to Dec 2024, so for the demo we anchor
// "today" to the end of the data. With live production data, change this line to:
//   const TODAY = new Date();
const TODAY = new Date('2024-12-31T00:00:00Z');

const LIMIT = 20;

// --- Minimal CSV parser (handles quoted fields and CRLF) ---
function parseCSV(text) {
  if (!text || typeof text !== 'string') return [];
  const rows = [];
  let row = [], field = '', inQuotes = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i], n = text[i + 1];
    if (inQuotes) {
      if (c === '"' && n === '"') { field += '"'; i++; }
      else if (c === '"') { inQuotes = false; }
      else { field += c; }
    } else {
      if (c === '"') { inQuotes = true; }
      else if (c === ',') { row.push(field); field = ''; }
      else if (c === '\n') { row.push(field); rows.push(row); row = []; field = ''; }
      else if (c === '\r') { /* ignore */ }
      else { field += c; }
    }
  }
  if (field.length > 0 || row.length > 0) { row.push(field); rows.push(row); }
  if (rows.length === 0) return [];
  const header = rows[0].map(h => h.trim());
  return rows.slice(1)
    .filter(r => r.length === header.length)
    .map(r => { const o = {}; header.forEach((h, i) => o[h] = r[i]); return o; });
}

// --- Read CSV text out of the upstream HTTP nodes ---
function getText(nodeName) {
  try {
    const j = $(nodeName).first().json;
    if (typeof j === 'string') return j;
    if (j && typeof j.data === 'string') return j.data;
    if (j && typeof j.body === 'string') return j.body;
    return '';
  } catch (e) {
    return '';
  }
}

const accounts = parseCSV(getText('Fetch Accounts'));
const subs     = parseCSV(getText('Fetch Subscriptions'));
let usageRows  = parseCSV(getText('Fetch Usage'));
const usageAvailable = usageRows.length > 0;

// --- Helpers ---
function toDate(s) {
  if (!s) return null;
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : d;
}
function daysBetween(a, b) { return Math.floor((a.getTime() - b.getTime()) / 86400000); }
function isChurned(v) { return v === 'True' || v === 'true' || v === '1'; }

// --- Most recent active subscription per account ---
const latest = {};
for (const s of subs) {
  if (s.end_date && s.end_date.trim() !== '') continue;   // skip ended subs
  const start = toDate(s.start_date);
  const cur = latest[s.account_id];
  if (!cur || (start && toDate(cur.start_date) && start > toDate(cur.start_date))) {
    latest[s.account_id] = s;
  }
}

// --- Usage aggregation (only if the usage file loaded) ---
const subToAccount = {};
for (const s of subs) subToAccount[s.subscription_id] = s.account_id;

const u30 = {}, u90 = {}, lastSeen = {};
if (usageAvailable) {
  const cut30 = new Date(TODAY.getTime() - 30 * 86400000);
  const cut90 = new Date(TODAY.getTime() - 90 * 86400000);
  for (const u of usageRows) {
    const aid = subToAccount[u.subscription_id];
    if (!aid) continue;
    const d = toDate(u.usage_date);
    if (!d) continue;
    const cnt = parseFloat(u.usage_count) || 0;
    if (d > cut90) u90[aid] = (u90[aid] || 0) + cnt;
    if (d > cut30) u30[aid] = (u30[aid] || 0) + cnt;
    if (!lastSeen[aid] || d > lastSeen[aid]) lastSeen[aid] = d;
  }
}
usageRows = null;  // free memory

// --- Score every active, non-churned account ---
const results = [];
let totalScored = 0;

for (const a of accounts) {
  if (isChurned(a.churn_flag)) continue;
  totalScored++;

  const sub = latest[a.account_id] || {};
  const signup = toDate(a.signup_date);
  const tenure = signup ? daysBetween(TODAY, signup) : 9999;

  let score = 0;
  const signals = [];

  if (tenure < 30)      { score += 40; signals.push('brand-new account — ' + tenure + (tenure === 1 ? ' day old' : ' days old')); }
  else if (tenure < 90) { score += 25; signals.push('new account — ' + tenure + ' days old'); }

  if (a.industry === 'DevTools') { score += 25; signals.push('DevTools segment (highest churn rate in the data)'); }

  let daysSince = null;
  if (usageAvailable) {
    const base = (u90[a.account_id] || 0) / 3;
    const recent = u30[a.account_id] || 0;
    const ratio = base > 0 ? recent / base : 1.0;
    if (ratio < 0.5)      { score += 15; signals.push('product usage down ' + Math.round((1 - ratio) * 100) + '% versus the prior period'); }
    else if (ratio < 0.7) { score += 8;  signals.push('product usage down ' + Math.round((1 - ratio) * 100) + '% versus the prior period'); }
    if (lastSeen[a.account_id]) {
      daysSince = daysBetween(TODAY, lastSeen[a.account_id]);
      if (daysSince > 7) signals.push('last login ' + daysSince + ' days ago');
    }
  }

  const billing = (sub.billing_frequency || '').toLowerCase();
  if (billing === 'monthly') { score += 10; signals.push('month-to-month contract (no annual commitment)'); }

  const seats = parseInt(sub.seats, 10) || 0;
  if (sub.plan_tier === 'Enterprise' && seats < 5) { score += 10; signals.push('Enterprise plan but fewer than 5 seats'); }

  if (score <= 0) continue;

  results.push({
    account_id: a.account_id,
    account_name: a.account_name || a.account_id,
    industry: a.industry || '',
    country: a.country || '',
    sub_plan: sub.plan_tier || 'unknown',
    seats: seats,
    mrr: parseFloat(sub.mrr_amount) || 0,
    risk_score: Math.min(score, 100),
    tenure_days: tenure,
    days_since_last_login: daysSince,
    billing: sub.billing_frequency || 'unknown',
    risk_signals: signals,
  });
}

results.sort((x, y) => y.risk_score - x.risk_score);
const top = results.slice(0, LIMIT);

return [{
  json: {
    accounts: top,
    count: top.length,
    total_scored: totalScored,
    generated_at: new Date().toISOString(),
    model_version: 'rule-based-v1-embedded',
    usage_signal_used: usageAvailable,
  }
}];

const response = $input.first().json;
const accounts = response.accounts;
const generatedAt = response.generated_at;
const totalScored = response.total_scored;

const today = new Date().toLocaleDateString('en-GB', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
});

const accountLines = accounts.map((a, i) => {
  const signals = a.risk_signals.join('; ');
  return [
    `${i + 1}. ${a.account_name} (${a.industry}, ${a.sub_plan} plan, $${a.mrr}/mo, ${a.seats} seats)`,
    `   Risk score: ${a.risk_score}/100`,
    `   Signals: ${signals || 'no specific signals'}`
  ].join('\n');
}).join('\n\n');

const prompt = `You are a customer success assistant for Ravenstack, a B2B SaaS platform.

Below are this week's top ${accounts.length} at-risk accounts scored by our churn prediction model. For each account, write a single plain-English sentence (maximum 20 words) that a customer success manager can act on immediately. Be specific — name the signal and what it implies for the customer relationship.

Accounts:
${accountLines}

Rules:
- One sentence per account, numbered to match the list above
- No preamble, no headers, no commentary after the list
- Write for a non-technical reader who knows the customer`;

const llmPayload = {
  model: 'claude-sonnet-4-6',
  max_tokens: 1000,
  messages: [{ role: 'user', content: prompt }]
};

return [{ json: { accounts, generatedAt, totalScored, today, llmPayload } }];

const promptData = $('Build LLM Prompt').first().json;
const accounts    = promptData.accounts;
const totalScored = promptData.totalScored;
const today       = promptData.today;

const llmResponse = $input.first().json;
const contentBlocks = llmResponse.content || [];
const rawText = (contentBlocks.find(c => c.type === 'text') || {}).text || '';

const alertLines = rawText
  .split('\n')
  .map(l => l.trim())
  .filter(l => /^\d+\./.test(l))
  .map(l => l.replace(/^\d+\.\s*/, ''));

const blocks = [
  { type: 'header', text: { type: 'plain_text', text: 'Weekly Churn Risk Digest', emoji: true } },
  { type: 'context', elements: [{ type: 'mrkdwn',
      text: `*${today}*  |  ${accounts.length} accounts flagged from ${totalScored} active  |  Model: rule-based v1` }] },
  { type: 'divider' }
];

// One section block per account keeps us well under Slack's 50-block limit.
accounts.forEach((acct, i) => {
  const alert = alertLines[i] || acct.risk_signals.join('; ') || 'Review account history.';
  const dot = acct.risk_score >= 65 ? ':red_circle:' : acct.risk_score >= 40 ? ':large_yellow_circle:' : ':large_green_circle:';
  const line =
    `${dot}  *${acct.account_name}*  —  *${acct.risk_score}/100*\n` +
    `${acct.sub_plan} · ${acct.seats} seats · $${acct.mrr}/mo · ${acct.country}\n` +
    `_${alert}_`;
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: line } });
});

blocks.push({ type: 'divider' });
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn',
  text: 'React: :white_check_mark: reached out   :next_track_button: skip this week   :speech_balloon: note in thread   |  Next digest: Monday 08:00' }] });

// Slack hard-caps at 50 blocks. Trim defensively if a future change pushes us over.
const safeBlocks = blocks.slice(0, 50);

return [{ json: { blocks: safeBlocks } }];
